# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Marginal-cost multicommodity broadcast.

    Each (dst, partition) pair is a commodity. We maintain a mutable price
    map p(e) = base_cost(e) * (1 + lam * load(e) / throughput(e)) where load
    counts partitions already routed through e. For each commodity, up to
    K=8 candidate simple paths are enumerated via nx.shortest_simple_paths
    on the priced graph; the cheapest candidate under current prices is
    committed (increasing load on its edges). Up to 3 greedy passes refine
    assignments; a pass is only accepted if the base-cost total does not
    regress against the current best plan. Fallback: if a dst has a single
    feasible path, all its partitions reuse it.
    """
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    dsts_eff = [d for d in dsts if d != src]

    def edge_data(s, t):
        if G.has_edge(s, t):
            return G[s][t]
        return G[t][s]

    def base_cost(s, t):
        ed = edge_data(s, t)
        c = ed.get("cost")
        return float(c) if c is not None else 0.0

    def capacity(s, t):
        ed = edge_data(s, t)
        tp = ed.get("throughput")
        return max(float(tp), 1e-9) if tp is not None else 1e9

    lam = 2.0
    K = 8
    passes = 3

    # load[e] = number of committed partitions through directed edge e
    load = {}

    def priced_graph():
        Pg = h.copy()
        for s, t in Pg.edges():
            Pg[s][t]["price"] = base_cost(s, t) * (1.0 + lam * load.get((s, t), 0) / capacity(s, t))
        return Pg

    def path_base_cost(path):
        return sum(base_cost(path[i], path[i + 1]) for i in range(len(path) - 1))

    def candidate_paths(dst):
        Pg = priced_graph()
        try:
            gen = nx.shortest_simple_paths(Pg, src, dst, weight="price")
            out = []
            for p in gen:
                out.append(p)
                if len(out) >= K:
                    break
            return out
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            return []

    def commit(path, sign):
        for i in range(len(path) - 1):
            key = (path[i], path[i + 1])
            load[key] = load.get(key, 0) + sign

    def plan_cost(plan):
        return sum(path_base_cost(p) for p in plan.values())

    # Greedy passes over all commodities in fixed order.
    best_assign = None
    best_cost = float("inf")
    for _ in range(passes):
        assign = {}
        for dst in dsts_eff:
            cands = candidate_paths(dst)
            if not cands:
                continue
            for j in range(num_partitions):
                best_p = min(cands, key=lambda p: path_base_cost(p) * (1.0 + lam * sum(load.get((p[i], p[i + 1]), 0) / capacity(p[i], p[i + 1]) for i in range(len(p) - 1))))
                assign[(dst, j)] = list(best_p)
                commit(best_p, +1)
        if not assign:
            break
        c = plan_cost(assign)
        if best_assign is None or c < best_cost:
            best_assign, best_cost = assign, c
        # reset load for next pass
        load.clear()

    if best_assign is None:
        # Fallback: plain Dijkstra once per dst, all partitions on it.
        for dst in dsts_eff:
            try:
                path = nx.dijkstra_path(h, src, dst, weight="cost")
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                continue
            for i in range(len(path) - 1):
                s, t = path[i], path[i + 1]
                for j in range(num_partitions):
                    bc_topology.append_dst_partition_path(dst, j, [s, t, edge_data(s, t)])
        return bc_topology

    # Guard: compare against incumbent-style all-Dijkstra baseline; keep
    # whichever plan has lower base cost.
    base = {}
    for dst in dsts_eff:
        try:
            p = nx.dijkstra_path(h, src, dst, weight="cost")
            base[dst] = p
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            base[dst] = None
    baseline_cost = sum(path_base_cost(p) * num_partitions for p in base.values() if p is not None)

    if baseline_cost <= best_cost:
        for dst, p in base.items():
            if p is None:
                continue
            for i in range(len(p) - 1):
                s, t = p[i], p[i + 1]
                for j in range(num_partitions):
                    bc_topology.append_dst_partition_path(dst, j, [s, t, edge_data(s, t)])
        return bc_topology

    # Emit best marginal-cost plan.
    for (dst, j), path in best_assign.items():
        for i in range(len(path) - 1):
            s, t = path[i], path[i + 1]
            bc_topology.append_dst_partition_path(dst, j, [s, t, edge_data(s, t)])

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)

